<?php
declare(strict_types=1);
require_once __DIR__.'/../cutting_import.php';require_once __DIR__.'/../cutting.php';require_once __DIR__.'/goal.php';
function cutting_importAction(string $action,array $input):array{
 $c=permit(['owner','technologist','chief','foreman']);manufacturingRequireStorage();
 if($action==='cutting_import_preview'){$o=orderRecord(textField($input,'order_id',32,true));return cuttingImportPreview($input,$c,$o);}
 if($action==='cutting_import_open')return cuttingImportPublic(cuttingImportRecord($c,textField($input,'id',32,true)));
 if($action==='cutting_import_ocr')return command($action,$input,function(array $c)use($input){$r=cuttingImportRecord($c,textField($input,'id',32,true));$page=numberField($input,'page',1,200);$meta=decode($r['metadata_json']);if(isset($meta['ocr_pages'][$page]))return cuttingImportPublic($r);$dir=dirname(__DIR__,2).'/storage/imports/'.$c['id'];$source=$dir.'/'.$r['id'].'.bin';if(!is_file($source))fail('Исходный файл недоступен',404);$text=cuttingRecognizeFile($source,$r['extension'],$page,$dir);$meta['ocr_pages'][$page]=$text;ksort($meta['ocr_pages']);$meta['ocr_next_page']=$page+1;$meta['recognition']='local_ocr_requires_review';$meta['warnings'][]='Распознанные поля требуют проверки человеком';$full=documentCleanText(implode("\n",$meta['ocr_pages']));query("UPDATE document_imports SET raw_text=?,safe_text='',metadata_json=?,state='extracted' WHERE id=? AND company_id=?",[$full,j($meta),$r['id'],$c['id']]);$r['raw_text']=$full;$r['metadata_json']=j($meta);return cuttingImportPublic($r);});
 if($action!=='cutting_import_source')fail('Неизвестное действие переноса',404);$file=$_FILES['document']??null;$paste=textField($input,'text',300000);$dir=dirname(__DIR__,2).'/storage/imports/'.$c['id'];if(!is_dir($dir)&&!@mkdir($dir,0700,true))fail('Разрешите PHP запись в storage/imports',503);file_put_contents(dirname($dir).'/.htaccess',"Require all denied\n");$id=uid();$path=$dir.'/'.$id.'.bin';$metadata=['origin'=>'cutting_import','warnings'=>[]];
 if($file){if(!is_array($file)||$file['error']!==UPLOAD_ERR_OK||!is_uploaded_file($file['tmp_name']))fail('Не удалось принять исходник');$extension=strtolower(pathinfo((string)$file['name'],PATHINFO_EXTENSION));if(!in_array($extension,['txt','csv','tsv','docx','xlsx','xls','pdf','png','jpg','jpeg','webp'],true))fail('Поддерживаются таблицы, DOCX, PDF и изображения');if($file['size']>DOCUMENT_MAX_BYTES)fail('Источник не должен превышать 12 МБ',413);$name=textField(['name'=>basename((string)$file['name'])],'name',240,true);$text='';
  if(in_array($extension,['png','jpg','jpeg','webp'],true)){$image=@getimagesize($file['tmp_name']);if(!$image||$image[0]*$image[1]>24000000)fail('Изображение некорректно или превышает 24 мегапикселя');$metadata['needs_ocr']=true;}
  else{try{$extracted=extractDocument($file['tmp_name'],$extension==='tsv'?'csv':$extension);$text=$extension==='docx'?(cuttingDocxTable($file['tmp_name'])??$extracted['text']):$extracted['text'];$metadata=array_replace($metadata,array_diff_key($extracted,['text'=>true]));}catch(AppError $error){if($extension!=='pdf')throw $error;$metadata['needs_ocr']=true;$metadata['warnings'][]=$error->getMessage();}}
  $hash=hash_file('sha256',$file['tmp_name']);$existing=one('SELECT * FROM document_imports WHERE company_id=? AND actor_id=? AND source_hash=?',[$c['id'],$_SESSION['user_id'],$hash]);if($existing)return cuttingImportPublic($existing);if(!move_uploaded_file($file['tmp_name'],$path))fail('Не удалось сохранить исходник',503);
 }else{if(!$paste)fail('Выберите файл или вставьте таблицу');$text=documentCleanText($paste);$extension='txt';$name='Таблица раскроя';$hash=hash('sha256',$text);if(file_put_contents($path,$text)===false)fail('Не удалось сохранить вставленную таблицу',503);}
 $metadata['bytes']=filesize($path);$metadata['source_file']=$id;$metadata['ocr_next_page']=1;
 query('INSERT INTO document_imports (id,company_id,actor_id,display_name,extension,source_hash,raw_text,safe_text,metadata_json) VALUES (?,?,?,?,?,?,?,?,?)',[$id,$c['id'],$_SESSION['user_id'],$name,$extension,$hash,$text,'',j($metadata)]);audit('cutting_source_saved',['document_id'=>$id,'format'=>$extension]);return cuttingImportPublic(cuttingImportRecord($c,$id));
}
